2: //
3: // Currently restricted by `md.validateLink()` to http/https/ftp
4: //
5: 'use strict';
6: 
7: 
8: var arrayReplaceAt = require('../common/utils').arrayReplaceAt;
9: var normalizeLink  = require('../common/utils').normalizeLink;
10: var Token          = require('../token');
11: 
12: 
13: function isLinkOpen(str) {
14:   return /^<a[>\s]/i.test(str);
15: }
16: function isLinkClose(str) {
17:   return /^<\/a\s*>/i.test(str);
18: }
19: 
20: 
21: module.exports = function linkify(state) {
22:   var i, j, l, tokens, token, currentToken, nodes, ln, text, pos, lastPos, level, htmlLinkLevel,
23:       blockTokens = state.tokens,
24:       links;
25: 
26:   if (!state.md.options.linkify) { return; }
27: 
28:   for (j = 0, l = blockTokens.length; j < l; j++) {
29:     if (blockTokens[j].type !== 'inline') { continue; }
30: 
31:     tokens = blockTokens[j].children;
32: 
33:     htmlLinkLevel = 0;
34: 
35:     // We scan from the end, to keep position when new tags added.
36:     // Use reversed logic in links start/end match
37:     for (i = tokens.length - 1; i >= 0; i--) {
38:       currentToken = tokens[i];
39: 
40:       // Skip content of markdown links
41:       if (currentToken.type === 'link_close') {
42:         i--;
43:         while (tokens[i].level !== currentToken.level && tokens[i].type !== 'link_open') {
44:           i--;
45:         }
46:         continue;
47:       }
48: 
49:       // Skip content of html tag links
50:       if (currentToken.type === 'html_inline') {
51:         if (isLinkOpen(currentToken.content) && htmlLinkLevel > 0) {
52:           htmlLinkLevel--;
53:         }
54:         if (isLinkClose(currentToken.content)) {
55:           htmlLinkLevel++;
56:         }
57:       }
58:       if (htmlLinkLevel > 0) { continue; }
59: 
60:       if (currentToken.type === 'text' && state.md.linkify.test(currentToken.content)) {
61: 
62:         text = currentToken.content;
63:         links = state.md.linkify.match(text);
64: 
65:         // Now split string to nodes
66:         nodes = [];
67:         level = currentToken.level;
68:         lastPos = 0;
69: 
70:         for (ln = 0; ln < links.length; ln++) {
71: 
72:           if (!state.md.validateLink(links[ln].url)) { continue; }
73: 
74:           pos = links[ln].index;
75: 
76:           if (pos > lastPos) {
77:             token         = new Token('text', '', 0);
78:             token.content = text.slice(lastPos, pos);
79:             token.level   = level;
80:             nodes.push(token);
81:           }
82: 
83:           token         = new Token('link_open', 'a', 1);
84:           token.attrs   = [ [ 'href', normalizeLink(links[ln].url) ] ];
85:           token.level   = level++;
86:           nodes.push(token);
87: 
88:           token         = new Token('text', '', 0);
89:           token.content = links[ln].text;
90:           token.level   = level;
91:           nodes.push(token);
92: 
